// dump inputs are real util-linux hexdump -C and xxd output; ftfy 6.3.1's
// fix_encoding for the UTF-8 repairs; CPython round trips for the others).
// Characters outside printable ASCII are written as \uXXXX escapes.
// ============================================================================

import { run, type CharsetInput, type CharsetResult } from "./compute";

/** The set id: the tool slug and the date the expected values were captured. */
export const GOLDEN_VECTOR_SET_ID = "charset-equivalency-golden-2026-10-03";

/** One vector: a name, what it shows, an input, and the pinned fields of its result. */
export interface CharsetVector {
  // A short stable name.
  id: string;
  // What it shows.
  note: string;
  // The input, exactly as the tool takes it.
  input: CharsetInput;
  // The pinned fields of the result.
  expect: Record<string, unknown>;
}

/** Bytes as upper-case hex pairs. */
const hex = (b: readonly number[]) => b.map((x) => x.toString(16).toUpperCase().padStart(2, "0")).join(" ");

/** Reduce a result to the fields a vector pins. */
export function pin(r: CharsetResult): Record<string, unknown> {
  // An encoding: bytes, BOM, counts, three styles, every charset, the read-back.
  if (r.mode === "encode") return { mode: r.mode, charset: r.result.charset, bytes: hex(r.result.bytes), bom: r.result.bom ? hex(r.result.bom) : null, codePoints: r.result.codePoints, unencodable: r.result.unencodable, failed: r.result.failed, styles: { python: r.styles.python, base64: r.styles.base64, percent: r.styles.percent }, everywhere: r.everywhere.map((w) => [w.charset, hex(w.bytes), w.unencodable]), readBack: r.readBack.map((x) => [x.charset, x.text, x.errors]) };
  // A decoding: what was read, how it decoded, every charset.
  if (r.mode === "decode") return { mode: r.mode, parsed: { format: r.parsed.format, dump: r.parsed.dump ?? null, error: r.parsed.error ?? null, bytes: hex(r.parsed.bytes) }, result: r.result ? { requested: r.result.requested, charset: r.result.charset, guess: r.result.guess ?? null, bom: r.result.bom, bomOverride: r.result.bomOverride, text: r.result.text, errors: r.result.units.filter((u) => u.error).map((u) => [u.at, u.len, u.error]) } : null, everywhere: r.everywhere.map((x) => [x.charset, x.text, x.errors]) };
  // A repair: the candidates.
  if (r.mode === "repair") return { mode: r.mode, inputScore: r.result.inputScore, candidates: r.result.candidates.map((c) => ({ text: c.text, steps: c.steps.map((s) => `${s.misread}>${s.original}`), evidence: c.evidence, lossy: c.lossy, lost: c.lost })) };
  // An error.
  return { mode: r.mode };
}

